package main

import (
	"fmt"
	"math"
	"math/rand"
	"sync"
	"time"
)

type XFetchItem struct {
	Value  string
	Delta  time.Duration // Время, затраченное на вычисление значения
	Expiry time.Time     // Момент жесткого истечения срока жизни
}

type XFetchCache struct {
	mu      sync.RWMutex
	storage map[string]*XFetchItem
	beta    float64 // Параметр агрессивности (обычно 1.0)
}

func NewXFetchCache(beta float64) *XFetchCache {
	return &XFetchCache{
		storage: make(map[string]*XFetchItem),
		beta:    beta,
	}
}

// ShouldRefresh вычисляет вероятностную формулу XFetch:
// now - delta * beta * ln(rnd) > expiry
func (c *XFetchCache) ShouldRefresh(item *XFetchItem) bool {
	now := time.Now()
	if now.After(item.Expiry) {
		return true // Уже жестко просрочен
	}

	// rand.Float64() возвращает [0.0, 1.0). Для ln исключаем 0.0:
	rnd := rand.Float64()
	if rnd <= 0.0 {
		rnd = 0.00001
	}

	// - delta * beta * ln(rnd)
	earlyExpirationOffset := -float64(item.Delta) * c.beta * math.Log(rnd)
	timeOffset := time.Duration(earlyExpirationOffset)

	// Если now + offset > Expiry -> пора обновлять!
	return now.Add(timeOffset).After(item.Expiry)
}

func (c *XFetchCache) GetOrFetch(key string, ttl time.Duration, fetcher func() (string, error)) (string, bool) {
	c.mu.RLock()
	item, ok := c.storage[key]
	c.mu.RUnlock()

	// Полный промах (холодный старт)
	if !ok {
		return c.refresh(key, ttl, fetcher), true
	}

	// Проверяем вероятностный триггер раннего обновления
	if c.ShouldRefresh(item) {
		// Запускаем упреждающее обновление в фоне
		go func() {
			c.refresh(key, ttl, fetcher)
		}()
	}

	return item.Value, false
}

func (c *XFetchCache) refresh(key string, ttl time.Duration, fetcher func() (string, error)) string {
	start := time.Now()
	val, err := fetcher()
	if err != nil {
		return ""
	}
	delta := time.Since(start)

	c.mu.Lock()
	c.storage[key] = &XFetchItem{
		Value:  val,
		Delta:  delta,
		Expiry: time.Now().Add(ttl),
	}
	c.mu.Unlock()

	return val
}

func main() {
	cache := NewXFetchCache(1.5) // beta = 1.5
	key := "weather:moscow"

	dbCalls := 0
	dbFetcher := func() (string, error) {
		dbCalls++
		time.Sleep(30 * time.Millisecond) // Тяжелый расчет
		return fmt.Sprintf("Temperature: +21C (v%d)", dbCalls), nil
	}

	// 1. Первый запрос (холодный старт)
	val, isCold := cache.GetOrFetch(key, 500*time.Millisecond, dbFetcher)
	fmt.Printf("1. Инициализация: val='%s', cold=%v\n", val, isCold)

	// 2. Имитируем поток запросов на протяжении 1 секунды
	start := time.Now()
	requests := 0
	for time.Since(start) < 1*time.Second {
		val, _ = cache.GetOrFetch(key, 500*time.Millisecond, dbFetcher)
		requests++
		time.Sleep(15 * time.Millisecond)
	}

	fmt.Printf("За 1 секунду обработано %d запросов.\n", requests)
	fmt.Printf("Всего фоновых вызовов БД (XFetch): %d (кэш ни разу не протух полностью!)\n", dbCalls)
	fmt.Printf("Текущее значение в кэше: %s\n", val)
}

package main

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

var (
	ErrNotFound       = errors.New("entity not found")
	SentinelNullValue = []byte("__NULL_OBJECT_SENTINEL__")
)

type Database struct {
	queriesCount int64
	records      map[int64]string
}

func (db *Database) Query(id int64) (string, error) {
	atomic.AddInt64(&db.queriesCount, 1)
	time.Sleep(10 * time.Millisecond) // Имитация поиска по индексу

	val, ok := db.records[id]
	if !ok {
		return "", ErrNotFound
	}
	return val, nil
}

type SafeNullCache struct {
	db       *Database
	cache    sync.Map
	nullTTL  time.Duration
	validTTL time.Duration
}

type cacheEntry struct {
	val       []byte
	expiresAt time.Time
}

func NewSafeNullCache(db *Database) *SafeNullCache {
	return &SafeNullCache{
		db:       db,
		nullTTL:  2 * time.Second, // Короткий TTL для отсутствующих записей
		validTTL: 10 * time.Minute,
	}
}

func (c *SafeNullCache) Get(ctx context.Context, id int64) (string, error) {
	key := fmt.Sprintf("user:%d", id)

	// 1. Проверяем кэш
	if raw, ok := c.cache.Load(key); ok {
		entry := raw.(cacheEntry)
		if time.Now().Before(entry.expiresAt) {
			// Проверяем sentinel
			if string(entry.val) == string(SentinelNullValue) {
				return "", ErrNotFound // Мгновенный отказ из кэша!
			}
			return string(entry.val), nil
		}
		c.cache.Delete(key)
	}

	// 2. Поход в базу данных
	val, err := c.db.Query(id)
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			// КЭШИРУЕМ ПУСТОЙ РЕЗУЛЬТАТ!
			c.cache.Store(key, cacheEntry{
				val:       SentinelNullValue,
				expiresAt: time.Now().Add(c.nullTTL),
			})
			return "", ErrNotFound
		}
		return "", err
	}

	// 3. Кэшируем валидный результат
	c.cache.Store(key, cacheEntry{
		val:       []byte(val),
		expiresAt: time.Now().Add(c.validTTL),
	})

	return val, nil
}

func main() {
	db := &Database{
		records: map[int64]string{
			100: "User: Elon Musk",
			200: "User: Satya Nadella",
		},
	}
	cache := NewSafeNullCache(db)
	ctx := context.Background()

	fmt.Println("1. Запрос существующего ID 100...")
	v, err := cache.Get(ctx, 100)
	fmt.Printf("Результат: '%s', err: %v\n", v, err)

	fmt.Println("\n2. Атака: 10 запросов подряд к несуществующему ID 999999...")
	for i := 1; i <= 10; i++ {
		_, err := cache.Get(ctx, 999999)
		if !errors.Is(err, ErrNotFound) {
			fmt.Println("Неожиданная ошибка:", err)
		}
	}

	fmt.Printf("\nИтого запросов к базе данных: %d\n", db.queriesCount)
	fmt.Printf("Из них к ID 100: 1 запрос, к несуществующему ID 999999: ровно 1 запрос (остальные 9 отбил кэш!)\n")
}

package main

import (
	"fmt"
	"sync"
)

type BloomFilter struct {
	mu    sync.RWMutex
	bits  []uint64
	size  uint64
	kHash uint64
}

func NewBloomFilter(sizeBits uint64, kHash uint64) *BloomFilter {
	words := (sizeBits + 63) / 64
	return &BloomFilter{
		bits:  make([]uint64, words),
		size:  sizeBits,
		kHash: kHash,
	}
}

// hash64 вычисляет базовый хеш для ключа
func (bf *BloomFilter) getHashes(key string) (uint64, uint64) {
	var h1 uint64 = 14695981039346656037
	var h2 uint64 = 5381
	for i := 0; i < len(key); i++ {
		h1 ^= uint64(key[i])
		h1 *= 1099511628211

		h2 = ((h2 << 5) + h2) + uint64(key[i])
	}
	return h1, h2
}

func (bf *BloomFilter) Add(key string) {
	bf.mu.Lock()
	defer bf.mu.Unlock()

	h1, h2 := bf.getHashes(key)
	for i := uint64(0); i < bf.kHash; i++ {
		// Кирш-Митценмахер метод генерации K хешей: h(i) = h1 + i*h2
		bitIdx := (h1 + i*h2) % bf.size
		wordIdx := bitIdx / 64
		bitPos := bitIdx % 64
		bf.bits[wordIdx] |= (1 << bitPos)
	}
}

func (bf *BloomFilter) Contains(key string) bool {
	bf.mu.RLock()
	defer bf.mu.RUnlock()

	h1, h2 := bf.getHashes(key)
	for i := uint64(0); i < bf.kHash; i++ {
		bitIdx := (h1 + i*h2) % bf.size
		wordIdx := bitIdx / 64
		bitPos := bitIdx % 64
		if (bf.bits[wordIdx] & (1 << bitPos)) == 0 {
			return false // Точно отсутствует!
		}
	}
	return true // Возможно, присутствует
}

type UserStoreWithBloom struct {
	bloom *BloomFilter
	db    map[string]string
}

func (s *UserStoreWithBloom) Get(id string) (string, string) {
	// Шаг 1: Проверка фильтром Блума
	if !s.bloom.Contains(id) {
		return "", "REJECTED_BY_BLOOM"
	}

	// Шаг 2: Только если фильтр сказал YES -> идем в БД
	val, ok := s.db[id]
	if !ok {
		return "", "FALSE_POSITIVE"
	}
	return val, "FOUND_IN_DB"
}

func main() {
	// Фильтр на 10 000 бит с 4 хеш-функциями
	bloom := NewBloomFilter(10_000, 4)
	db := make(map[string]string)

	// Заполняем существующие ID (от 1 до 500)
	for i := 1; i <= 500; i++ {
		id := fmt.Sprintf("user:%d", i)
		db[id] = fmt.Sprintf("UserData_%d", i)
		bloom.Add(id)
	}

	store := &UserStoreWithBloom{bloom: bloom, db: db}

	// 1. Проверяем валидный ключ
	val, status := store.Get("user:42")
	fmt.Printf("user:42 -> %s [%s]\n", val, status)

	// 2. Проверяем 10 000 несуществующих ключей
	rejected := 0
	falsePositives := 0

	for i := 501; i <= 10500; i++ {
		id := fmt.Sprintf("user:%d", i)
		_, st := store.Get(id)
		if st == "REJECTED_BY_BLOOM" {
			rejected++
		} else if st == "FALSE_POSITIVE" {
			falsePositives++
		}
	}

	fmt.Printf("\n=== РЕЗУЛЬТАТЫ ФИЛЬТРА БЛУМА ===\n")
	fmt.Printf("Проверено несуществующих ключей: 10000\n")
	fmt.Printf("Отсечено без обращения к базе данных: %d (%.2f%%)\n", rejected, float64(rejected)/100.0)
	fmt.Printf("Ложноположительных пропусков в БД: %d (%.2f%%)\n", falsePositives, float64(falsePositives)/100.0)
}

package main

import (
	"fmt"
	"math/rand"
	"time"
)

// ApplyJitter добавляет симметричный процентный джиттер к базовому TTL.
// Например, base = 100s, jitterFactor = 0.2 -> TTL от 80s до 120s.
func ApplyJitter(baseTTL time.Duration, jitterFactor float64) time.Duration {
	if jitterFactor <= 0 {
		return baseTTL
	}
	// Случайный коэффициент в диапазоне [-jitterFactor, +jitterFactor]
	delta := (rand.Float64()*2 - 1) * jitterFactor
	multiplier := 1.0 + delta

	return time.Duration(float64(baseTTL) * multiplier)
}

func main() {
	itemCount := 100_000
	baseTTL := 60 * time.Second
	jitterFactor := 0.20 // 20% джиттер (+-12 секунд)

	// Моделируем моменты экспирации без джиттера
	noJitterBuckets := make(map[int]int)
	for i := 0; i < itemCount; i++ {
		sec := int(baseTTL.Seconds())
		noJitterBuckets[sec]++
	}

	// Моделируем моменты экспирации с джиттером
	jitterBuckets := make(map[int]int)
	for i := 0; i < itemCount; i++ {
		actual := ApplyJitter(baseTTL, jitterFactor)
		sec := int(actual.Seconds())
		jitterBuckets[sec]++
	}

	fmt.Println("=== СРАВНЕНИЕ ЭКСПИРАЦИИ 100 000 КЛЮЧЕЙ ===")
	fmt.Printf("1. Без джиттера (Cache Avalanche):\n")
	fmt.Printf("   Секунда 59: %d ключей истекло\n", noJitterBuckets[59])
	fmt.Printf("   Секунда 60: %d ключей истекло (КАТАСТРОФИЧЕСКИЙ ПИК!)\n", noJitterBuckets[60])
	fmt.Printf("   Секунда 61: %d ключей истекло\n\n", noJitterBuckets[61])

	fmt.Printf("2. С джиттером 20%% (Равномерное распределение):\n")
	minSec, maxSec := 48, 72
	maxInJitter := 0
	for s := minSec; s <= maxSec; s++ {
		c := jitterBuckets[s]
		if c > maxInJitter {
			maxInJitter = c
		}
	}

	fmt.Printf("   Диапазон истечения: от %dс до %dс (окно %d секунд)\n", minSec, maxSec, maxSec-minSec)
	fmt.Printf("   Пиковая нагрузка в секунду: %d ключей (в %.1f раз меньше!)\n",
		maxInJitter, float64(noJitterBuckets[60])/float64(maxInJitter))

	fmt.Println("\nПример распределения по секундам с джиттером:")
	for s := minSec; s <= minSec+6; s++ {
		fmt.Printf("   t = %dc: %d ключей\n", s, jitterBuckets[s])
	}
}

package main

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

type CustomerAccount struct {
	ID      string
	Balance int64
}

type WriteThroughService struct {
	mu       sync.RWMutex
	l1Cache  map[string]CustomerAccount
	dbStore  map[string]CustomerAccount
	simDBErr bool
}

func NewWriteThroughService() *WriteThroughService {
	return &WriteThroughService{
		l1Cache: make(map[string]CustomerAccount),
		dbStore: make(map[string]CustomerAccount),
	}
}

func (s *WriteThroughService) Get(ctx context.Context, id string) (CustomerAccount, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	// При Write-Through кэш всегда прогрет!
	acc, ok := s.l1Cache[id]
	return acc, ok
}

func (s *WriteThroughService) Save(ctx context.Context, acc CustomerAccount) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	// Шаг 1: Запись в базу данных (первоисточник правды)
	if s.simDBErr {
		return errors.New("db error: disk I/O failure on commit")
	}
	s.dbStore[acc.ID] = acc

	// Шаг 2: Синхронная сквозная запись в кэш
	s.l1Cache[acc.ID] = acc

	return nil
}

func main() {
	svc := NewWriteThroughService()
	ctx := context.Background()

	acc := CustomerAccount{ID: "acc_777", Balance: 50000}

	fmt.Println("1. Успешная сквозная запись аккаунта...")
	err := svc.Save(ctx, acc)
	fmt.Printf("Save err: %v\n", err)

	val, found := svc.Get(ctx, "acc_777")
	fmt.Printf("Мгновенное чтение из L1: %+v (найдено: %v)\n\n", val, found)

	fmt.Println("2. Попытка обновления с ошибкой в базе данных...")
	svc.simDBErr = true
	badUpdate := CustomerAccount{ID: "acc_777", Balance: 999999}
	err = svc.Save(ctx, badUpdate)
	fmt.Printf("Save err: %v\n", err)

	valAfterErr, _ := svc.Get(ctx, "acc_777")
	fmt.Printf("Баланс в кэше после сбоя БД: %d (НЕ изменился, консистентность соблюдена!)\n", valAfterErr.Balance)
}

package main

import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

type Record struct {
	Key   string
	Value string
}

type WriteBehindCache struct {
	mu         sync.RWMutex
	memory     map[string]string
	queue      chan Record
	wg         sync.WaitGroup
	batchSize  int
	dbInserts  int64
	dbRowsSaved int64
}

func NewWriteBehindCache(queueCap, batchSize int, flushInterval time.Duration) *WriteBehindCache {
	c := &WriteBehindCache{
		memory:    make(map[string]string),
		queue:     make(chan Record, queueCap),
		batchSize: batchSize,
	}

	c.wg.Add(1)
	go c.flushWorker(flushInterval)

	return c
}

func (c *WriteBehindCache) Get(key string) (string, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	val, ok := c.memory[key]
	return val, ok
}

func (c *WriteBehindCache) Set(key, value string) {
	c.mu.Lock()
	c.memory[key] = value
	c.mu.Unlock()

	// Асинхронная отправка в очередь записи
	c.queue <- Record{Key: key, Value: value}
}

func (c *WriteBehindCache) flushWorker(interval time.Duration) {
	defer c.wg.Done()
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	buffer := make([]Record, 0, c.batchSize)

	flush := func() {
		if len(buffer) == 0 {
			return
		}
		// Имитация пакетной вставки в БД
		atomic.AddInt64(&c.dbInserts, 1)
		atomic.AddInt64(&c.dbRowsSaved, int64(len(buffer)))
		time.Sleep(20 * time.Millisecond) // Задержка записи батча
		buffer = buffer[:0]
	}

	for {
		select {
		case rec, ok := <-c.queue:
			if !ok {
				flush() // Сбрасываем остаток при закрытии
				return
			}
			buffer = append(buffer, rec)
			if len(buffer) >= c.batchSize {
				flush()
			}
		case <-ticker.C:
			flush()
		}
	}
}

func (c *WriteBehindCache) Close() {
	close(c.queue)
	c.wg.Wait()
}

func main() {
	cache := NewWriteBehindCache(10000, 50, 100*time.Millisecond)

	fmt.Println("Запись 200 событий в режиме Write-Behind...")
	start := time.Now()

	for i := 1; i <= 200; i++ {
		cache.Set(fmt.Sprintf("metric:cpu:core_%d", i%4), fmt.Sprintf("val_%d", i))
	}
	writeDuration := time.Since(start)
	fmt.Printf("Клиент завершил 200 записей мгновенно за %v!\n", writeDuration)

	// Проверяем, что в оперативной памяти данные уже доступны сразу
	val, _ := cache.Get("metric:cpu:core_1")
	fmt.Printf("Мгновенный Get из памяти: %s\n", val)

	// Закрываем кэш с гарантированным сбросом (Graceful Flush)
	cache.Close()

	fmt.Printf("\n=== РЕЗУЛЬТАТЫ БАТЧИНГА В БАЗУ ДАННЫХ ===\n")
	fmt.Printf("Фактических SQL-транзакций (батчей): %d\n", cache.dbInserts)
	fmt.Printf("Всего строк сброшено в БД: %d\n", cache.dbRowsSaved)
}

package main

import (
	"context"
	"encoding/json"
	"fmt"
	"sync"
	"time"
)

type InvalidationEvent struct {
	Key      string `json:"key"`
	SenderID string `json:"sender_id"`
}

// MockRedisPubSub симулирует централизованный брокер Pub/Sub Redis
type MockRedisPubSub struct {
	mu          sync.Mutex
	subscribers map[string]chan []byte
}

func NewMockRedisPubSub() *MockRedisPubSub {
	return &MockRedisPubSub{
		subscribers: make(map[string]chan []byte),
	}
}

func (b *MockRedisPubSub) Subscribe(nodeID string) <-chan []byte {
	b.mu.Lock()
	defer b.mu.Unlock()
	ch := make(chan []byte, 100)
	b.subscribers[nodeID] = ch
	return ch
}

func (b *MockRedisPubSub) Publish(msg []byte) {
	b.mu.Lock()
	defer b.mu.Unlock()
	for _, ch := range b.subscribers {
		select {
		case ch <- msg:
		default:
			// Защита от зависания при медленном подписчике
		}
	}
}

// ClusterNode представляет инстанс сервиса в Kubernetes
type ClusterNode struct {
	NodeID string
	l1     sync.Map
	broker *MockRedisPubSub
}

func NewClusterNode(nodeID string, broker *MockRedisPubSub) *ClusterNode {
	n := &ClusterNode{
		NodeID: nodeID,
		broker: broker,
	}

	// Запускаем слушатель инвалидаций
	ch := broker.Subscribe(nodeID)
	go n.listenInvalidations(ch)

	return n
}

func (n *ClusterNode) listenInvalidations(ch <-chan []byte) {
	for raw := range ch {
		var evt InvalidationEvent
		if err := json.Unmarshal(raw, &evt); err != nil {
			continue
		}
		// Игнорируем собственные события
		if evt.SenderID == n.NodeID {
			continue
		}
		// Инвалидируем ключ в локальной памяти
		n.l1.Delete(evt.Key)
		fmt.Printf("[%s] Инвалидирован ключ '%s' по сообщению от %s\n", n.NodeID, evt.Key, evt.SenderID)
	}
}

func (n *ClusterNode) UpdateData(key, newVal string) {
	// 1. Обновляем локально
	n.l1.Store(key, newVal)

	// 2. Рассылаем широковещательное уведомление другим нодам
	evt := InvalidationEvent{
		Key:      key,
		SenderID: n.NodeID,
	}
	bytes, _ := json.Marshal(evt)
	n.broker.Publish(bytes)
}

func main() {
	broker := NewMockRedisPubSub()

	// Поднимаем 3 реплики сервиса
	nodeA := NewClusterNode("pod-srv-node-A", broker)
	nodeB := NewClusterNode("pod-srv-node-B", broker)
	nodeC := NewClusterNode("pod-srv-node-C", broker)

	key := "pricing:plan:pro"

	// Все ноды закэшировали старый план
	nodeA.l1.Store(key, "Price: 99$")
	nodeB.l1.Store(key, "Price: 99$")
	nodeC.l1.Store(key, "Price: 99$")

	fmt.Println("Все ноды имеют в L1 кэше: Price: 99$")

	// Клиент отправляет запрос на изменение цены на Ноду А
	fmt.Println("\nНода А обновляет цену на 129$ и рассылает инвалидацию...")
	nodeA.UpdateData(key, "Price: 129$")

	time.Sleep(50 * time.Millisecond) // Даем брокеру доставить сообщения

	// Проверяем состояние кэшей
	valA, _ := nodeA.l1.Load(key)
	_, foundB := nodeB.l1.Load(key)
	_, foundC := nodeC.l1.Load(key)

	fmt.Printf("\nРезультаты состояния L1 кэшей на нодах:\n")
	fmt.Printf("Нода A (автор): '%s'\n", valA)
	fmt.Printf("Нода B: в кэше найдено = %v (устаревшие данные очищены!)\n", foundB)
	fmt.Printf("Нода C: в кэше найдено = %v (устаревшие данные очищены!)\n", foundC)
}

package main

import (
	"fmt"
	"sync"
	"time"
)

type PushMessage struct {
	Type string
	Keys []string
}

type SimulatedRedisServer struct {
	mu            sync.Mutex
	data          map[string]string
	trackingTable map[string]map[int]chan PushMessage
}

func NewSimulatedRedisServer() *SimulatedRedisServer {
	return &SimulatedRedisServer{
		data:          make(map[string]string),
		trackingTable: make(map[string]map[int]chan PushMessage),
	}
}

func (s *SimulatedRedisServer) RegisterClient(clientID int) chan PushMessage {
	return make(chan PushMessage, 50)
}

func (s *SimulatedRedisServer) Get(clientID int, key string, pushCh chan PushMessage) (string, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()

	if _, ok := s.trackingTable[key]; !ok {
		s.trackingTable[key] = make(map[int]chan PushMessage)
	}
	s.trackingTable[key][clientID] = pushCh

	val, ok := s.data[key]
	return val, ok
}

func (s *SimulatedRedisServer) Set(authorID int, key, val string) {
	s.mu.Lock()
	defer s.mu.Unlock()

	s.data[key] = val

	if clients, ok := s.trackingTable[key]; ok {
		for cid, ch := range clients {
			if cid != authorID {
				select {
				case ch <- PushMessage{Type: "invalidate", Keys: []string{key}}:
				default:
				}
			}
		}
		delete(s.trackingTable, key)
	}
}

type ClientSideCache struct {
	id     int
	server *SimulatedRedisServer
	pushCh chan PushMessage
	l1     sync.Map
}

func NewClientSideCache(id int, server *SimulatedRedisServer) *ClientSideCache {
	pushCh := server.RegisterClient(id)
	c := &ClientSideCache{
		id:     id,
		server: server,
		pushCh: pushCh,
	}

	go c.listenPushes()
	return c
}

func (c *ClientSideCache) listenPushes() {
	for msg := range c.pushCh {
		if msg.Type == "invalidate" {
			for _, k := range msg.Keys {
				c.l1.Delete(k)
				fmt.Printf("[Client #%d] RESP3 PUSH: Ключ '%s' инвалидирован сервером Redis!\n", c.id, k)
			}
		}
	}
}

func (c *ClientSideCache) Get(key string) string {
	if v, ok := c.l1.Load(key); ok {
		return v.(string) + " (from L1)"
	}

	val, ok := c.server.Get(c.id, key, c.pushCh)
	if !ok {
		return "NOT_FOUND"
	}

	c.l1.Store(key, val)
	return val + " (from Redis L2 -> cached to L1)"
}

func main() {
	redisServer := NewSimulatedRedisServer()
	redisServer.data["user:cfg:dark_mode"] = "true"

	clientA := NewClientSideCache(101, redisServer)
	clientB := NewClientSideCache(102, redisServer)

	fmt.Println("1. Клиент А запрашивает ключ (холодный старт)...")
	fmt.Println("Ответ:", clientA.Get("user:cfg:dark_mode"))

	fmt.Println("\n2. Клиент А запрашивает ключ повторно...")
	fmt.Println("Ответ:", clientA.Get("user:cfg:dark_mode"))

	fmt.Println("\n3. Клиент B изменяет значение ключа на сервере Redis...")
	redisServer.Set(clientB.id, "user:cfg:dark_mode", "false")

	time.Sleep(50 * time.Millisecond)

	fmt.Println("\n4. Клиент А снова запрашивает ключ после push-инвалидации...")
	fmt.Println("Ответ:", clientA.Get("user:cfg:dark_mode"))
}

package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

type TTLConfig struct {
	L1TTL          time.Duration
	L2TTL          time.Duration
	StaleThreshold time.Duration
}

type L1Item struct {
	Val       string
	ExpiredAt time.Time
}

type SafeMultiTTLService struct {
	mu     sync.RWMutex
	l1     map[string]L1Item
	l2     map[string]string
	l2Down bool
	cfg    TTLConfig
}

func NewSafeMultiTTLService(cfg TTLConfig) *SafeMultiTTLService {
	return &SafeMultiTTLService{
		l1:  make(map[string]L1Item),
		l2:  make(map[string]string),
		cfg: cfg,
	}
}

func (s *SafeMultiTTLService) Get(ctx context.Context, key string, dbLoader func() (string, error)) (string, string, error) {
	s.mu.RLock()
	item, inL1 := s.l1[key]
	s.mu.RUnlock()

	now := time.Now()

	if inL1 && now.Before(item.ExpiredAt) {
		return item.Val, "L1_FRESH", nil
	}

	if !s.l2Down {
		s.mu.RLock()
		l2Val, inL2 := s.l2[key]
		s.mu.RUnlock()

		if inL2 {
			s.mu.Lock()
			s.l1[key] = L1Item{Val: l2Val, ExpiredAt: now.Add(s.cfg.L1TTL)}
			s.mu.Unlock()
			return l2Val, "L2_HIT_BACKFILL_L1", nil
		}
	} else {
		if inL1 && now.Before(item.ExpiredAt.Add(s.cfg.StaleThreshold)) {
			return item.Val, "L1_STALE_GRACEFUL_FALLBACK", nil
		}
	}

	fresh, err := dbLoader()
	if err != nil {
		return "", "ERROR", err
	}

	s.mu.Lock()
	if !s.l2Down {
		s.l2[key] = fresh
	}
	s.l1[key] = L1Item{Val: fresh, ExpiredAt: now.Add(s.cfg.L1TTL)}
	s.mu.Unlock()

	return fresh, "DB_FETCH", nil
}

func main() {
	cfg := TTLConfig{
		L1TTL:          200 * time.Millisecond,
		L2TTL:          10 * time.Minute,
		StaleThreshold: 1 * time.Second,
	}
	svc := NewSafeMultiTTLService(cfg)
	ctx := context.Background()

	loader := func() (string, error) {
		return "AccountBalance: $54,200", nil
	}

	key := "acc:balance:1001"

	v, src, _ := svc.Get(ctx, key, loader)
	fmt.Printf("[1] %s -> %s\n", src, v)

	time.Sleep(50 * time.Millisecond)
	v, src, _ = svc.Get(ctx, key, loader)
	fmt.Printf("[2] %s -> %s\n", src, v)

	time.Sleep(250 * time.Millisecond)
	v, src, _ = svc.Get(ctx, key, loader)
	fmt.Printf("[3] %s -> %s\n", src, v)

	svc.l2Down = true
	time.Sleep(250 * time.Millisecond)
	v, src, _ = svc.Get(ctx, key, loader)
	fmt.Printf("[4] %s -> %s (Redis упал, но сервис отдал stale из L1!)\n", src, v)
}

package main

import (
	"container/list"
	"fmt"
	"sync"
)

type lruEntry struct {
	key string
	val string
}

type SimpleLRU struct {
	capacity  int
	items     map[string]*list.Element
	evictList *list.List
	mu        sync.Mutex
}

func NewSimpleLRU(cap int) *SimpleLRU {
	return &SimpleLRU{
		capacity:  cap,
		items:     make(map[string]*list.Element),
		evictList: list.New(),
	}
}

func (c *SimpleLRU) Get(key string) (string, bool) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if elem, ok := c.items[key]; ok {
		c.evictList.MoveToFront(elem)
		return elem.Value.(*lruEntry).val, true
	}
	return "", false
}

func (c *SimpleLRU) Put(key, val string) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if elem, ok := c.items[key]; ok {
		c.evictList.MoveToFront(elem)
		elem.Value.(*lruEntry).val = val
		return
	}

	if c.evictList.Len() >= c.capacity {
		oldest := c.evictList.Back()
		if oldest != nil {
			c.evictList.Remove(oldest)
			delete(c.items, oldest.Value.(*lruEntry).key)
		}
	}

	entry := &lruEntry{key: key, val: val}
	elem := c.evictList.PushFront(entry)
	c.items[key] = elem
}

type SimulatedTinyLFU struct {
	*SimpleLRU
	frequencySketch map[string]int
}

func NewTinyLFU(cap int) *SimulatedTinyLFU {
	return &SimulatedTinyLFU{
		SimpleLRU:       NewSimpleLRU(cap),
		frequencySketch: make(map[string]int),
	}
}

func (t *SimulatedTinyLFU) PutWithAdmission(key, val string) bool {
	t.mu.Lock()
	defer t.mu.Unlock()

	if t.evictList.Len() < t.capacity {
		entry := &lruEntry{key: key, val: val}
		elem := t.evictList.PushFront(entry)
		t.items[key] = elem
		return true
	}

	victimElem := t.evictList.Back()
	victimKey := victimElem.Value.(*lruEntry).key

	candidateFreq := t.frequencySketch[key]
	victimFreq := t.frequencySketch[victimKey]

	if candidateFreq <= victimFreq {
		return false // Отклоняем кандидата на входе!
	}

	t.evictList.Remove(victimElem)
	delete(t.items, victimKey)

	entry := &lruEntry{key: key, val: val}
	elem := t.evictList.PushFront(entry)
	t.items[key] = elem
	return true
}

func main() {
	capacity := 4

	// 1. Тест обычного LRU
	lru := NewSimpleLRU(capacity)
	for i := 1; i <= capacity; i++ {
		lru.Put(fmt.Sprintf("hot_%d", i), "val")
	}

	for i := 1; i <= capacity; i++ {
		lru.Put(fmt.Sprintf("scan_trash_%d", i), "val")
	}

	fmt.Println("=== РЕЗУЛЬТАТ ОБЫЧНОГО LRU ПОСЛЕ СКАНА ===")
	for i := 1; i <= capacity; i++ {
		k := fmt.Sprintf("hot_%d", i)
		_, found := lru.Get(k)
		fmt.Printf("Ключ %s найден: %v (ВЫМЫТ!)\n", k, found)
	}

	// 2. Тест TinyLFU
	tiny := NewTinyLFU(capacity)
	for i := 1; i <= capacity; i++ {
		k := fmt.Sprintf("hot_%d", i)
		tiny.frequencySketch[k] = 100
		tiny.Put(k, "val")
	}

	rejected := 0
	for i := 1; i <= capacity; i++ {
		k := fmt.Sprintf("scan_trash_%d", i)
		tiny.frequencySketch[k] = 1
		if !tiny.PutWithAdmission(k, "val") {
			rejected++
		}
	}

	fmt.Println("\n=== РЕЗУЛЬТАТ TINYLFU ПОСЛЕ СКАНА ===")
	fmt.Printf("Отклонено разовых ключей на входе: %d из %d\n", rejected, capacity)
	for i := 1; i <= capacity; i++ {
		k := fmt.Sprintf("hot_%d", i)
		_, found := tiny.Get(k)
		fmt.Printf("Ключ %s найден: %v (УСПЕШНО СОХРАНЕН!)\n", k, found)
	}
}

package main

import (
	"bytes"
	"compress/gzip"
	"encoding/json"
	"fmt"
	"io"
	"strings"
	"time"
)

const (
	FlagRaw        byte = 0x00
	FlagCompressed byte = 0x01
	ThresholdBytes      = 1024
)

type CompressionMiddleware struct {
	threshold int
}

func NewCompressionMiddleware(threshold int) *CompressionMiddleware {
	return &CompressionMiddleware{threshold: threshold}
}

func (m *CompressionMiddleware) Encode(data []byte) ([]byte, bool, error) {
	if len(data) < m.threshold {
		res := make([]byte, 1+len(data))
		res[0] = FlagRaw
		copy(res[1:], data)
		return res, false, nil
	}

	var buf bytes.Buffer
	buf.WriteByte(FlagCompressed)

	gw := gzip.NewWriter(&buf)
	if _, err := gw.Write(data); err != nil {
		return nil, false, err
	}
	if err := gw.Close(); err != nil {
		return nil, false, err
	}

	return buf.Bytes(), true, nil
}

func (m *CompressionMiddleware) Decode(payload []byte) ([]byte, error) {
	if len(payload) == 0 {
		return nil, nil
	}

	flag := payload[0]
	data := payload[1:]

	switch flag {
	case FlagRaw:
		return data, nil
	case FlagCompressed:
		gr, err := gzip.NewReader(bytes.NewReader(data))
		if err != nil {
			return nil, err
		}
		defer gr.Close()
		return io.ReadAll(gr)
	default:
		return nil, fmt.Errorf("unknown compression flag: 0x%x", flag)
	}
}

func main() {
	middleware := NewCompressionMiddleware(ThresholdBytes)

	smallData := []byte(`{"user_id": 42, "role": "admin"}`)
	encSmall, wasComp, _ := middleware.Encode(smallData)
	fmt.Printf("1. Мелкий объект: Исходный = %d Б, В кэше = %d Б, Сжат = %v\n",
		len(smallData), len(encSmall), wasComp)

	largeCatalog := map[string]interface{}{
		"category": "HighLoad Servers",
		"desc":     strings.Repeat("Enterprise Distributed Memory Architecture in Go. ", 150),
		"items":    []int{101, 102, 103, 104, 105, 106, 107, 108, 109, 110},
	}
	largeData, _ := json.Marshal(largeCatalog)

	tStart := time.Now()
	encLarge, wasComp, _ := middleware.Encode(largeData)
	compTime := time.Since(tStart)

	tDecompStart := time.Now()
	decLarge, _ := middleware.Decode(encLarge)
	decompTime := time.Since(tDecompStart)

	ratio := float64(len(encLarge)) / float64(len(largeData)) * 100

	fmt.Printf("\n2. Крупный объект:\n   Исходный размер:   %d байт\n   Размер в кэше:     %d байт\n   Сэкономлено:       %.1f%% памяти!\n   Время сжатия:      %v\n   Время распаковки:  %v\n   Корректность:      %v\n",
		len(largeData), len(encLarge), 100.0-ratio, compTime, decompTime, len(decLarge) == len(largeData))
}

package main

import (
	"container/list"
	"fmt"
	"sync"
	"time"
)

type BoundedItem struct {
	key  string
	val  []byte
	cost int64
}

type MemoryBoundedCache struct {
	mu             sync.Mutex
	maxBytes       int64
	currentBytes   int64
	items          map[string]*list.Element
	lruList        *list.List
	evictionsCount int64
}

func NewMemoryBoundedCache(maxBytes int64) *MemoryBoundedCache {
	return &MemoryBoundedCache{
		maxBytes: maxBytes,
		items:    make(map[string]*list.Element),
		lruList:  list.New(),
	}
}

func (c *MemoryBoundedCache) estimateCost(key string, val []byte) int64 {
	return int64(len(key) + len(val) + 48)
}

func (c *MemoryBoundedCache) Set(key string, val []byte) {
	c.mu.Lock()
	defer c.mu.Unlock()

	cost := c.estimateCost(key, val)
	if cost > c.maxBytes {
		return
	}

	if elem, ok := c.items[key]; ok {
		c.currentBytes -= elem.Value.(*BoundedItem).cost
		c.lruList.Remove(elem)
		delete(c.items, key)
	}

	for c.currentBytes+cost > c.maxBytes && c.lruList.Len() > 0 {
		oldest := c.lruList.Back()
		if oldest == nil {
			break
		}
		item := oldest.Value.(*BoundedItem)
		c.currentBytes -= item.cost
		c.lruList.Remove(oldest)
		delete(c.items, item.key)
		c.evictionsCount++
	}

	item := &BoundedItem{key: key, val: val, cost: cost}
	elem := c.lruList.PushFront(item)
	c.items[key] = elem
	c.currentBytes += cost
}

func (c *MemoryBoundedCache) EmergencyPrune(percent float64) {
	c.mu.Lock()
	defer c.mu.Unlock()

	targetReduction := int64(float64(c.currentBytes) * percent)
	var freed int64
	for freed < targetReduction && c.lruList.Len() > 0 {
		oldest := c.lruList.Back()
		if oldest == nil {
			break
		}
		item := oldest.Value.(*BoundedItem)
		c.currentBytes -= item.cost
		freed += item.cost
		c.lruList.Remove(oldest)
		delete(c.items, item.key)
		c.evictionsCount++
	}
}

func main() {
	const maxCap = 10 * 1024
	cache := NewMemoryBoundedCache(maxCap)

	for i := 1; i <= 15; i++ {
		cache.Set(fmt.Sprintf("payload_%d", i), make([]byte, 1000))
	}

	fmt.Printf("Потребление: %d / %d байт\n", cache.currentBytes, cache.maxBytes)
	fmt.Printf("Элементов в памяти: %d, Вытеснено: %d\n", len(cache.items), cache.evictionsCount)

	time.Sleep(50 * time.Millisecond)
	cache.EmergencyPrune(0.40)

	fmt.Printf("После экстренной очистки: %d байт, осталось: %d\n", cache.currentBytes, len(cache.items))
}

